// No items in queue, exit gracefully
console.log('No queue items available, exiting');
return [];

// Merge all context and make decision
const crypto = require('crypto');

const item = $input.item.json;
const invoice = item; // Already has invoice data
const customerContext = item.customer_context || {};
const suppression = item.suppression || { email_suppressed: false, sms_suppressed: false };
const promiseToPay = item.promise_to_pay || null;

const tenantId = item.tenant_id;
const now = new Date();
const nowIso = now.toISOString();

// Environment config
const autoSendMaxCents = parseInt($env.AUTO_SEND_MAX_AMOUNT_CENTS || '1000000');
const humanEscalationDays = parseInt($env.HUMAN_ESCALATION_DAYS || '31');
const dryRun = $env.DRY_RUN_MODE === 'true';

// Compute days overdue
const dueDate = new Date(invoice.due_date);
const daysOverdue = Math.floor((now - dueDate) / (1000 * 60 * 60 * 24));

// Decision object
const decision = {
  now_iso: nowIso,
  days_overdue: daysOverdue,
  stage: null,
  tone: null,
  channel: null,
  template_id: null,
  send_allowed: false,
  block_reason: null,
  dedupe_bucket_id: null,
  idempotency_key: null,
  message_hash: null,
  dry_run: dryRun
};

// GATE: Promise to pay active
if (promiseToPay && promiseToPay.promise_date) {
  decision.block_reason = 'promise_to_pay_active';
  decision.send_allowed = false;
  return { ...item, decision };
}

// GATE: Status not collectible
const nonCollectibleStatuses = ['paid', 'void', 'disputed', 'in_collection'];
if (nonCollectibleStatuses.includes(invoice.status)) {
  decision.block_reason = `status_not_collectible_${invoice.status}`;
  decision.send_allowed = false;
  return { ...item, decision };
}

// Determine stage
if (daysOverdue >= humanEscalationDays) {
  decision.stage = '4_human_escalation';
  decision.tone = 'n/a';
  decision.channel = 'human_task';
  decision.block_reason = 'stage4_escalation_required';
  decision.send_allowed = false;
  return { ...item, decision };
} else if (daysOverdue >= 16) {
  decision.stage = '3_final_notice';
  decision.tone = 'firm';
  decision.template_id = 'final_notice';
} else if (daysOverdue >= 8) {
  decision.stage = '2_second_notice';
  decision.tone = 'professional';
  decision.template_id = 'second_notice';
} else {
  decision.stage = '1_friendly_reminder';
  decision.tone = 'friendly';
  decision.template_id = 'gentle_reminder';
}

// GATE: High value
if (invoice.amount_due_cents > autoSendMaxCents) {
  decision.block_reason = 'high_value_requires_review';
  decision.send_allowed = false;
  return { ...item, decision };
}

// Choose channel
const consent = customerContext.consent || { can_email: false, can_sms: false };
const channelPref = customerContext.channel_preference || 'email';

if (channelPref === 'email' && consent.can_email && !suppression.email_suppressed) {
  decision.channel = 'email';
} else if (channelPref === 'sms' && consent.can_sms && !suppression.sms_suppressed) {
  decision.channel = 'sms';
  decision.template_id = decision.template_id.replace('notice', 'sms_short');
} else if (consent.can_email && !suppression.email_suppressed) {
  decision.channel = 'email';
} else if (consent.can_sms && !suppression.sms_suppressed) {
  decision.channel = 'sms';
  decision.template_id = 'sms_short_1';
} else {
  decision.block_reason = 'no_consent_or_suppressed';
  decision.send_allowed = false;
  return { ...item, decision };
}

// Compute dedupe bucket
const stageDedupeHours = {
  '1_friendly_reminder': parseInt($env.STAGE1_DEDUPE_HOURS || '48'),
  '2_second_notice': parseInt($env.STAGE2_DEDUPE_HOURS || '72'),
  '3_final_notice': parseInt($env.STAGE3_DEDUPE_HOURS || '120')
};
const dedupeSeconds = stageDedupeHours[decision.stage] * 3600;
const epochSeconds = Math.floor(now.getTime() / 1000);
decision.dedupe_bucket_id = Math.floor(epochSeconds / dedupeSeconds);

// Allow send (gates passed)
decision.send_allowed = true;

return { ...item, decision };

// Blocked - create human task
const item = $input.item.json;
const decision = item.decision;

const task = {
  tenant_id: item.tenant_id,
  priority: decision.stage === '4_human_escalation' ? 'urgent' : 'normal',
  task_type: decision.block_reason,
  title: `Invoice ${item.invoice_number}: ${decision.block_reason}`,
  description: `Invoice: ${item.invoice_number}\nCustomer: ${item.customer_name}\nAmount: ${item.currency} ${(item.amount_due_cents / 100).toFixed(2)}\nDays Overdue: ${decision.days_overdue}\nReason: ${decision.block_reason}`,
  invoice_id: item.invoice_id,
  customer_id: item.customer_id,
  amount_due_cents: item.amount_due_cents,
  days_overdue: decision.days_overdue,
  stage: decision.stage,
  status: 'open'
};

return task;

// Check quiet hours
const item = $input.item.json;
const decision = item.decision;
const customerContext = item.customer_context || {};

const customerTz = customerContext.timezone || $env.DEFAULT_TIMEZONE || 'America/Los_Angeles';
const quietStart = $env.QUIET_HOURS_START || '20:00';
const quietEnd = $env.QUIET_HOURS_END || '08:00';

// TODO: Implement timezone-aware quiet hours check
// For MVP, we'll allow all sends
const inQuietHours = false;

if (inQuietHours) {
  decision.block_reason = 'quiet_hours';
  decision.send_allowed = false;
}

return item;

