// Check if dedupe insert succeeded
const item = $input.item.json;

if (item.error) {
  // Unique constraint violation - duplicate detected
  item.decision.block_reason = 'dedupe_conflict';
  item.decision.send_allowed = false;
  item.dedupe_insert_failed = true;
} else {
  item.dedupe_insert_failed = false;
  item.reminder_send_id = item.id;
}

return item;

// Render message template
const item = $input.item.json;
const decision = item.decision;
const crypto = require('crypto');

// Template data
const templateData = {
  customer_name: item.customer_name,
  invoice_number: item.invoice_number,
  amount_due: (item.amount_due_cents / 100).toFixed(2),
  currency: item.currency,
  days_overdue: decision.days_overdue,
  payment_link: item.payment_link || 'https://pay.example.com/pending'
};

// Templates
const templates = {
  gentle_reminder: {
    subject: `Friendly Reminder: Invoice #${templateData.invoice_number}`,
    body: `Hi ${templateData.customer_name},\n\nJust a quick reminder that invoice #${templateData.invoice_number} for ${templateData.currency} ${templateData.amount_due} is now ${templateData.days_overdue} days past due.\n\nYou can pay here: ${templateData.payment_link}\n\nIf you've already sent payment, please disregard this message. If there's any issue preventing payment, reply here so we can help.\n\nThank you,\nAccounts Team\n\n---\nTo stop receiving payment reminders, click here: {{UNSUBSCRIBE_LINK}}`
  },
  second_notice: {
    subject: `Second Notice: Invoice #${templateData.invoice_number} (${templateData.days_overdue} days overdue)`,
    body: `Hi ${templateData.customer_name},\n\nFollowing up on invoice #${templateData.invoice_number} for ${templateData.currency} ${templateData.amount_due}. It is now ${templateData.days_overdue} days overdue.\n\nPayment link: ${templateData.payment_link}\n\nIf there's an issue preventing payment, please reply so we can work out the next steps.\n\nThank you,\nAccounts Team\n\n---\nTo stop receiving payment reminders, click here: {{UNSUBSCRIBE_LINK}}`
  },
  final_notice: {
    subject: `Action Needed: Invoice #${templateData.invoice_number}`,
    body: `Hi ${templateData.customer_name},\n\nInvoice #${templateData.invoice_number} for ${templateData.currency} ${templateData.amount_due} is now ${templateData.days_overdue} days past due.\n\nPlease use the payment link below or reply to coordinate a resolution:\n${templateData.payment_link}\n\nThank you,\nAccounts Team\n\n---\nTo stop receiving payment reminders, click here: {{UNSUBSCRIBE_LINK}}`
  },
  sms_short_1: `Hi ${templateData.customer_name} — invoice #${templateData.invoice_number} (${templateData.currency} ${templateData.amount_due}) is ${templateData.days_overdue} days past due. Pay: ${templateData.payment_link} Reply STOP to opt out.`
};

const template = templates[decision.template_id] || templates.gentle_reminder;

// Compute message hash
const messageBody = decision.channel === 'email' ? template.body : template;
const messageHash = crypto.createHash('sha256').update(messageBody).digest('hex').substring(0, 16);

// Compute idempotency key
const idempotencyKey = crypto.createHash('sha256')
  .update(`${item.tenant_id}:${item.invoice_id}:${decision.stage}:${decision.channel}:${decision.dedupe_bucket_id}:${messageHash}`)
  .digest('hex');

decision.message_hash = messageHash;
decision.idempotency_key = idempotencyKey;

item.message = {
  subject: template.subject || null,
  body: messageBody,
  template_id: decision.template_id
};

return item;

