// Check if outbound request insert succeeded
const item = $input.item.json;

if (item.error) {
  // Already sent (retry detected)
  item.already_sent = true;
  console.log(`Idempotency key ${item.decision.idempotency_key} already exists - skipping send`);
} else {
  item.already_sent = false;
  item.outbound_request_id = item.id;
}

return item;

// Dry run - simulate success
const item = $input.item.json;

console.log('DRY RUN: Would send', item.decision.channel, 'to', item.customer_email || item.customer_phone);
console.log('Subject:', item.message.subject);
console.log('Body preview:', item.message.body.substring(0, 100) + '...');

item.provider_result = {
  provider: 'dry_run',
  message_id: `dry_run_${Date.now()}`,
  status: 'simulated',
  timestamp: new Date().toISOString()
};

return item;
